{
  "case_id": "xsu_sg_006_work_history_information",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret fastslår, at det normalt ikke er Udbetaling Danmark, der vurderer ansøgningen, men SU-myndigheden (Styrelsen for Institutioner og Uddannelsesstøtte). Det modsiger kilderne, hvor Udbetaling Danmark er den vurderende myndighed (vejledning 3.4.1.3, SU-bek. §§ 36-37). Svaret nævner heller ikke Skattestyrelsen som kilde til arbejdstimer og indkomst. Det nævner ikke, at arbejde under studiet også indgår, og heller ikke den særlige relevans af arbejdsophør, der skyldes andre forhold end funktionsnedsættelsen. Svaret tilføjer desuden ukildebelagte udsagn."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Ingen af de fire kritiske elementer er dækket tilstrækkeligt. Skattestyrelsen som kilde til arbejdstimer og indkomst mangler. Svaret nævner kun generelt jobhistorik, men ikke at ansøgerens egne oplysninger skal angives i ansøgningen. Det mangler, at arbejde før ansøgningen navnlig kan indgå, når ophøret skyldtes andre forhold og funktionsnedsættelsen ikke er forværret. Arbejde under studiet er ikke nævnt."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Svaret bruger en del af sin plads på at afvise, at det er Udbetaling Danmark, der vurderer, og giver derefter en generel opremsning af oplysninger. Det besvarer ikke væsentlige dele af spørgsmålet, nemlig hvilke oplysninger Udbetaling Danmark bruger og hvorfra."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer ukildebelagt indhold: at SU-myndigheden og Styrelsen for Institutioner og Uddannelsesstøtte vurderer i stedet for Udbetaling Danmark, kriteriet 'nærmest ude af stand til at have et studiejob', at arbejdsevne er adskilt fra fribeløbsreglerne, samt en liste over oplysninger (honorarer, tilpasninger, årsag til jobophør). Intet af dette findes i det udleverede materiale."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer, at et indtægtsbeløb eller tidligere job ikke automatisk afgør sagen, og at oplysningerne indgår i en samlet vurdering. Til gengæld mangler forbeholdet om, at arbejde før ansøgningen navnlig er relevant, når ophøret skyldtes andre forhold, og funktionsnedsættelsen ikke er forværret efter ophøret."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret afviser Udbetaling Danmarks rolle og besvarer derefter spørgsmålet om oplysninger ud fra en anden myndighed. Det er internt usammenhængende i forhold til spørgsmålet og kilderne. Den præmis, der afviser Udbetaling Danmark, er forkert og understøtter ikke den videre gennemgang."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Svaret bruger passende modale formuleringer som 'kan indgå' og 'afgør ikke automatisk', og det gør ikke skønsmæssige elementer absolutte. Den forkerte påstand om, hvem der er myndighed, vedrører kompetence og ikke modalitet."
    }
  },
  "xhaile_coverage": {
    "A18": {
      "label": "no",
      "reason": "Svaret nævner ikke, at oplysninger om arbejdstimer og indkomst indhentes fra Skattestyrelsen. Det nævner kun generelt løn og arbejdstimer."
    },
    "A19": {
      "label": "partial",
      "reason": "Svaret nævner jobhistorik og oplysninger om arbejde, men ikke at ansøgeren selv skal angive tidligere arbejdsforhold i ansøgningen. Det knytter heller ikke oplysningerne til Udbetaling Danmark."
    },
    "A20": {
      "label": "no",
      "reason": "Svaret dækker ikke, at arbejde før ansøgningen navnlig kan indgå, når ophøret skyldtes andre forhold og funktionsnedsættelsen ikke er forværret. Det siger heller ikke, at arbejde under studiet indgår."
    }
  },
  "overall_notes": "Svaret indeholder en væsentlig juridisk fejl, idet det afviser, at Udbetaling Danmark vurderer sagen, og det mangler alle fire kritiske elementer. Det angiver ingen kilder. Det bevarer kun forbeholdet om, at indkomst eller tidligere job ikke automatisk afgør sagen."
}

